package com.rescuefarm.ui.seller;import com.rescuefarm.service.seller.SellerDashboardSnapshot;public final class SellerDashboardState{public enum Status{VERIFYING,LOADING,READY,EMPTY,NOT_APPROVED,ERROR}private final Status status;private final SellerDashboardSnapshot snapshot;private final String message;private SellerDashboardState(Status s,SellerDashboardSnapshot x,String m){status=s;snapshot=x;message=m==null?"":m;}public static SellerDashboardState of(Status s,SellerDashboardSnapshot x,String m){return new SellerDashboardState(s,x,m);}public Status getStatus(){return status;}public SellerDashboardSnapshot getSnapshot(){return snapshot;}public String getMessage(){return message;}}
